// SacVerde team page hero backgrounds (designs picked 10/31/2026). Names and stats come from live data.
const TEAM_ART_FONTS = "https://fonts.googleapis.com/css2?family=Anton&family=Archivo+Black&family=Bangers&family=Black+Ops+One&family=Cinzel:wght@900&family=IM+Fell+English:ital@0;1&family=JetBrains+Mono:wght@700&family=Pacifico&family=Permanent+Marker&family=Playfair+Display:wght@900&family=UnifrakturMaguntia&display=swap";

(function(){
  if(document.getElementById('tbg-fonts')) return;
  const l=document.createElement('link'); l.id='tbg-fonts'; l.rel='stylesheet'; l.href=TEAM_ART_FONTS; document.head.appendChild(l);
  const st=document.createElement('style'); st.textContent=`
.tbg-hero{position:relative;overflow:hidden;border-radius:14px;height:520px;border:1px solid var(--line);margin-bottom:4px;isolation:isolate}
.tbg-stage{position:absolute;top:0;right:0;width:1200px;height:520px;overflow:hidden;transform-origin:top right;pointer-events:none}
.tbg-shade{position:absolute;inset:0;pointer-events:none;display:none;opacity:.92;background:linear-gradient(90deg,var(--tbg-bg) 0%,var(--tbg-bg) 30%,transparent 85%)}
.tbg-content{position:relative;height:100%;box-sizing:border-box;padding:24px 32px 28px;display:flex;flex-direction:column;gap:8px;max-width:640px}
.tbg-top{display:flex;justify-content:flex-start}
.tbg-top select{background:rgba(10,10,12,.65);color:#fff;border:1px solid rgba(255,255,255,.25);border-radius:8px;padding:6px 10px;font-size:13px}
.tbg-bar{width:110px;height:5px;border-radius:2px}
.tbg-cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin-top:12px;max-width:540px}
.tbg-card{padding:12px 14px;display:flex;flex-direction:column;gap:2px}
.tbg-card .v{font-size:24px;font-weight:800;color:#fff}
.tbg-card .k{font-size:11px;letter-spacing:1px}
@media (max-width:900px){.tbg-hero{height:440px}.tbg-stage{transform:scale(.846)}.tbg-shade{display:block}}
@media (max-width:600px){.tbg-hero{height:600px}.tbg-stage{transform:scale(.77)}.tbg-shade{opacity:1;background:linear-gradient(180deg,transparent 0%,transparent 40%,var(--tbg-bg) 66%)}.tbg-content{padding:18px 16px 20px}.tbg-cards{gap:8px}.tbg-card{padding:10px}.tbg-card .v{font-size:19px}}
`; document.head.appendChild(st);
})();

function tbgGet(o, path){ return path.split('.').reduce((a,k)=>a==null?a:a[k], o); }
function tbgEsc(v){ return String(v==null?'':v).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }
// Tiny renderer for the design templates: {{a.b}} holes and <sc-for list="{{x}}" as="y"> loops
function tbgRender(str, vals){
  let out = '', i = 0;
  while(true){
    const s = str.indexOf('<sc-for', i);
    if(s < 0){ out += str.slice(i); break; }
    out += str.slice(i, s);
    const tagEnd = str.indexOf('>', s);
    const tag = str.slice(s, tagEnd+1);
    const list = (tag.match(/list="\{\{\s*([\w$.]+)\s*\}\}"/)||[])[1], as = (tag.match(/as="(\w+)"/)||[])[1];
    let depth = 1, j = tagEnd+1, close = -1;
    while(depth){ const o = str.indexOf('<sc-for', j), c = str.indexOf('</sc-for>', j);
      if(c < 0) break; if(o >= 0 && o < c){ depth++; j = o+7; } else { depth--; j = c+9; if(!depth) close = c; } }
    const inner = str.slice(tagEnd+1, close);
    (tbgGet(vals, list)||[]).forEach((item, idx)=>{ out += tbgRender(inner, Object.assign({}, vals, {[as]: item, $index: idx})); });
    i = close + 9;
  }
  return out.replace(/\{\{\s*([\w$.]+)\s*\}\}/g, (m, p)=>tbgEsc(tbgGet(vals, p)));
}
const TBG_SUFFIX = /^(jr\.?|sr\.?|ii|iii|iv|v)$/i;
function tbgSur(name){
  const w = String(name||'').trim().split(/\s+/); if(w.length < 2) return w[0]||'';
  let end = w.length; const jr = /^jr\.?$/i.test(w[end-1]);
  while(end > 1 && TBG_SUFFIX.test(w[end-1])) end--;
  let s = w[end-1]; if(end >= 3 && /^(st\.?|van|de|del|la|le|di)$/i.test(w[end-2])) s = w[end-2]+' '+s;
  return (s + (jr ? ' Jr.' : '')).toUpperCase();
}
function tbgRoster(t, info){
  const all = [...(t.roster||[]), ...(t.ir||[]), ...(t.taxi||[])].filter(p=>p && p.name && p.pos!=='DST');
  all.sort((a,b)=>(b.salary||0)-(a.salary||0));
  const seen = new Set(), list = all.filter(p=>!seen.has(p.name) && seen.add(p.name));
  const n = list.map(p=>tbgSur(p.name));
  return {
    list, n, full: list.map(p=>p.name), active: (t.roster||[]).length,
    pf: Math.round(+(info.pf||0)),
    sur: tbgSur,
    title: s=>s.split(' ').map(w=>w.charAt(0)+w.slice(1).toLowerCase()).join(' '),
    pos: (p, i)=>{ const x = list.filter(q=>q.pos===p)[i]; return x ? tbgSur(x.name) : (n[i]||''); },
    cyc: k=>{ const out=[]; for(let i=0;i<k;i++) out.push(n.length ? n[i % n.length] : ''); return out; }
  };
}
