  "Milky Wet Hogs": {bg: "#101820", eb: "font-size: 12px; font-weight: 700; letter-spacing: 3px; color: #ffb612;", tag: "GRADE A WHOLE HOG", h1: "margin: 0; font-family: Anton, Impact, sans-serif; font-size: clamp(40px, 7.4vw, 84px); line-height: 1; font-weight: 400; letter-spacing: 1px; text-transform: uppercase; color: #ffffff;", sub: "#c6c9cc", card: "background: rgba(26, 34, 42, 0.92); border: 1px solid #3a434c; border-radius: 10px; padding: 14px 16px; display: flex; flex-direction: column; gap: 2px;", label: "font-size: 11px; letter-spacing: 1px; color: #aab0b6;",
    tpl: "\n  <sc-for list=\"{{splash}}\" as=\"s\" hint-placeholder-count=\"14\">\n    <div aria-hidden=\"true\" style=\"{{s.style}}\"></div>\n  </sc-for>\n  <div aria-hidden=\"true\" style=\"position: absolute; left: 600px; right: 0; top: 0; height: 40px; background: #f7f7f2; border-radius: 0 0 40% 30% / 0 0 100% 100%;\"></div>\n  <sc-for list=\"{{drips}}\" as=\"d\" hint-placeholder-count=\"7\">\n    <div aria-hidden=\"true\" style=\"{{d.style}}\"></div>\n  </sc-for>\n  <div aria-hidden=\"true\" style=\"position: absolute; left: 780px; top: 54px; width: 300px; transform: rotate(4deg); background: #ffffff; color: #000000; border: 2px solid #000000; box-sizing: border-box; padding: 8px 12px; font-family: Helvetica, Arial, sans-serif; box-shadow: 0 18px 30px rgba(0, 0, 0, 0.55);\">\n    <div style=\"font-family: 'Archivo Black', Arial Black, sans-serif; font-size: 34px; line-height: 1; letter-spacing: -1px;\">Nutrition Facts</div>\n    <div style=\"font-size: 13px; border-bottom: 1px solid #000000; padding: 3px 0;\">1 Hog Roster per serving</div>\n    <div style=\"display: flex; justify-content: space-between; font-size: 14px; font-weight: 800; border-bottom: 8px solid #000000; padding: 2px 0;\"><span>Serving size</span><span>{{count}}</span></div>\n    <div style=\"display: flex; justify-content: space-between; align-items: flex-end; border-bottom: 4px solid #000000; padding: 2px 0;\"><span style=\"font-family: 'Archivo Black', Arial Black, sans-serif; font-size: 24px;\">Calories</span><span style=\"font-family: 'Archivo Black', Arial Black, sans-serif; font-size: 34px; line-height: 1;\">{{pf}}</span></div>\n    <div style=\"font-size: 11px; font-weight: 800; text-align: right; border-bottom: 1px solid #000000; padding: 2px 0;\">Salary ($)</div>\n    <sc-for list=\"{{facts}}\" as=\"f\" hint-placeholder-count=\"10\">\n      <div style=\"display: flex; justify-content: space-between; font-size: 13px; border-bottom: 1px solid #000000; padding: 2px 0;\"><span><b>{{f.name}}</b></span><span>{{f.sal}}</span></div>\n    </sc-for>\n    <div style=\"font-size: 10px; padding-top: 4px; line-height: 1.25;\">Contains: milk, hogs, Pittsburgh. Wet. Shake well before kickoff.</div>\n  </div>\n  <div aria-hidden=\"true\" style=\"position: absolute; inset: 0; background: linear-gradient(90deg, rgba(16, 24, 32, 1) 0%, rgba(16, 24, 32, 0.94) 42%, rgba(16, 24, 32, 0.05) 58%, rgba(16, 24, 32, 0) 100%);\"></div>"},
