"K2's Kings": function(R){
const n = R.n;
return { s0: n[0] || '', s1: n.slice(1, 4).join(' · '), s2: n.slice(4, 7).join(' · '), s3: n.slice(7, 11).join(' · ') };
},
"Roaring Hoogy": function(R){
const n = 24, x0 = 470, dx = 26;
const noise = [0, 18, -10, 25, 8, 30, -14, 22, 12, -8, 28, 16, -20, 34, 10, 26, -6, 30, 18, -12, 36, 20, 30, 44];
let level = 500;
const candles = [], tops = [];
for (let i = 0; i < n; i++) {
const move = noise[i] * 0.7 + 4;
const open = level, close = level - move;
const up = close < open;
const top = Math.min(open, close), h = Math.max(8, Math.abs(open - close));
const col = up ? '#2bdc7a' : '#ee3a2e';
const x = x0 + i * dx;
candles.push({ wick: 'position: absolute; left: ' + (x + 7) + 'px; top: ' + (top - 14) + 'px; width: 2px; height: ' + (h + 28) + 'px; background: ' + col + '; opacity: 0.7;', body: 'position: absolute; left: ' + x + 'px; top: ' + top + 'px; width: 16px; height: ' + h + 'px; background: ' + col + '; border-radius: 2px;' });
tops.push([x, top - 14]);
level = close;
}
const names = R.n.slice(0, 7).reverse();
const at = [5, 8, 11, 14, 17, 20, 23].slice(7 - names.length);
const labels = names.map((t, k) => {
const [x, y] = tops[at[k]];
return { text: t, style: "position: absolute; left: " + (x - 30) + "px; top: " + (y - 34) + "px; font-family: 'JetBrains Mono', monospace; font-weight: 700; font-size: 13px; letter-spacing: 1px; color: #0a0a0b; background: " + (k === names.length - 1 ? '#2bdc7a' : '#e6e6ea') + "; padding: 3px 7px; border-radius: 3px; white-space: nowrap;" };
});
const smoke = [0, 1, 2, 3, 4, 5, 6, 7, 8].map(k => {
const s = 14 + k * 6, x = 960 - k * 22 - s / 2, y = 150 + k * 20 - s / 2;
return { style: 'position: absolute; left: ' + x + 'px; top: ' + y + 'px; width: ' + s + 'px; height: ' + s + 'px; border-radius: 50%; background: radial-gradient(circle at 40% 35%, rgba(235, 235, 240, ' + (0.42 - k * 0.04) + '), rgba(150, 150, 160, 0) 70%);' };
});
return { candles, labels, smoke };
},
