function tbgOrd(n){ const s=["th","st","nd","rd"], v=n%100; return n+(s[(v-20)%10]||s[v]||s[0]); }
function tbgLeagueRank(name){
  try{ if(typeof LIVE==='undefined' || !LIVE.standings || typeof SEASON==='undefined' || SEASON===2025) return null;
    const wk = Math.max(...Object.keys(LIVE.standings).map(Number)); const r = (LIVE.standings[wk]||{})[LIVE.teamId[name]];
    return r ? tbgOrd(r) : null; }catch(e){ return null; }
}
// Returns the hero HTML for a team, or null when the team has no design (falls back to the plain header)
function teamHero(name, t, selectHtml, recText){
  const A = TEAM_ART[name], V = TEAM_ART_VALS[name]; if(!A || !V || !t) return null;
  const i = t.info || {};
  let art = '';
  try{ art = tbgRender(A.tpl, V(tbgRoster(t, i))); }catch(e){ console.error('team art', name, e); return null; }
  const rank = tbgLeagueRank(name);
  const standLbl = rank ? 'LEAGUE RANK' : 'DIVISION RANK', standVal = rank || i.standing || '—';
  const div = (i.division||'').toUpperCase();
  const ebColor = (A.eb.match(/color: ([^;]+);/)||[])[1] || '#fff';
  const card = (k, v)=>`<div class="tbg-card" style="${A.card}"><span class="k" style="${A.label}">${k}</span><span class="v">${v}</span></div>`;
  return `<div class="tbg-hero" style="background:${A.bg};--tbg-bg:${A.bg}">
    <div class="tbg-stage" aria-hidden="true"><div style="position:absolute;inset:0;background:${A.bg}"></div>${art}</div>
    <div class="tbg-shade"></div>
    <div class="tbg-content">
      <div class="tbg-top">${selectHtml||''}</div>
      <div style="flex-grow:1"></div>
      <div class="tbg-bar" style="background:${ebColor}"></div>
      <div style="${A.eb}">${tbgEsc(div)}${A.tag?' · '+tbgEsc(A.tag):''}</div>
      <h1 style="${A.h1}">${tbgEsc(name)}</h1>
      <div style="font-size:15px;color:${A.sub}">${i.owners?'Manager: '+tbgEsc(i.owners):''}</div>
      <div class="tbg-cards">${card((typeof SEASON!=='undefined'?SEASON:'')+' RECORD', tbgEsc(recText||'—'))}${card('POINTS FOR', Math.round(+(i.pf||0)))}${card(standLbl, tbgEsc(standVal))}</div>
    </div>
  </div>`;
}
